    }

    /**
     * @notice Remove validator ID from storage array
     * @dev Efficiently removes validator by swapping with last element
     * @param valId The validator ID to remove
     */
    function _removeValidatorFromArray(uint64 valId) internal {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        for (uint256 i = 0; i < $._validators.length; ++i) {
            if ($._validators[i] == valId) {
                $._validators[i] = $._validators[$._validators.length - 1];
                $._validators.pop();
                break;
            }
        }
    }

    /**
     * @dev Cache validator statistics from precompile to improve gas efficiency
     * @notice This function fetches fresh data from the staking precompile for all validators
     *         and stores it locally to avoid expensive precompile calls during normal operations
     */
    function _cacheValidatorStats() internal {
        uint256 _cachedTotalAssets = 0;
        BaseVaultStorage storage $ = _getBaseVaultStorage();

        // Fetch and cache delegator info for each active validator
        uint64[] memory _validators = getValidators();
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint64 _valId = _validators[_i];
            DelInfo memory _delInfo = _getDelegatorInfo(_valId, address(this)); // Expensive precompile call
            $._cachedDelegatorInfo[_valId] = _delInfo;
            // Sum total assets: active stake + pending stake changes
            _cachedTotalAssets += _delInfo.stake + _delInfo.deltaStake + _delInfo.nextDeltaStake;
        }

        // Reset pending delta tracking since we just refreshed from source of truth
        $._cachedTotalNetPendingDelegations = 0;
        $._cachedTotalAssets = _cachedTotalAssets;
    }

    /**
     * @notice Get total assets under management including pending operations
     * @dev Calculates total stake across all validators plus pending redelegations
     * @return Total assets in wei (active stake + pending redelegation amounts)
     */
    function totalAssets() external view returns (uint256) {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        return uint256(int256($._cachedTotalAssets + $._totalPendingRedelegation) + $._cachedTotalNetPendingDelegations);
    }

    /**
     * @notice Conditionally refresh cache if enough time has passed
     * @dev Only refreshes if more than delegatorInfoUpdateInterval has passed since last update
     */
    function refreshCacheCheck() external {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if (
            block.timestamp - $._lastDelegatorInfoUpdateTimestamp > $._delegatorInfoUpdateInterval
                || $._lastDelegatorInfoUpdateTimestamp == 0
        ) {
            _refreshCache();
        }
    }

    /**
     * @notice Force refresh the validator cache immediately
     * @dev Bypasses time interval check and updates cache with fresh precompile data
     */
    function refreshCache() external {
        _refreshCache();
    }

    /**
     * @dev Internal function to refresh cached validator statistics
     * @notice Updates cached data and sets new timestamp
     */
    function _refreshCache() internal {
        _cacheValidatorStats();
        _getBaseVaultStorage()._lastDelegatorInfoUpdateTimestamp = block.timestamp;
    }

    /**
     * @notice Set the minimum withdrawal amount for users
     * @dev Updates the minimum amount users can withdraw in a single transaction
     * @param _amount The minimum withdrawal amount in wei (must be less than 10,000 ether)
     */
    function setMinUserWithdrawAmount(uint256 _amount) external onlyOwner {
        if (_amount >= 10000 ether) revert ErrInvalidAmount(_amount);
        _getBaseVaultStorage()._minUserWithdrawAmount = _amount;
        emit MinUserWithdrawAmountUpdated(_amount);
    }

    /**
     * @notice Set the delegator info cache update interval
     * @dev Updates how often the cached delegator info can be refreshed
     * @param _interval The cache update interval in seconds (must be between 1 minute and 24 hours)
     */
    function setDelegatorInfoUpdateInterval(uint256 _interval) external onlyOwner {
        if (_interval < 1 minutes || _interval > 24 hours) revert ErrInvalidAmount(_interval);
        _getBaseVaultStorage()._delegatorInfoUpdateInterval = _interval;
        emit DelegatorInfoUpdateIntervalChanged(_interval);
    }

    function setEpochSeconds(uint256 _epochSeconds) external onlyOwner {
        _getBaseVaultStorage()._epochSeconds = _epochSeconds;
        emit EpochSecondsUpdated(_epochSeconds);
    }

    /**
     * @notice Get the timestamp of the last reward claim
     * @dev Returns when rewards were last claimed from all validators
     * @return The timestamp of the last reward claim
     */
    function lastRewardsClaimTimestamp() external view virtual returns (uint256) {
        return _getBaseVaultStorage()._lastRewardsClaimTimestamp;
    }

    /**
     * @notice Get the maximum delay allowed between reward claims
     * @dev Returns the maximum time allowed between reward claims
     * @return The maximum delay in seconds
     */
    function maxRewardsClaimDelay() external view virtual returns (uint256) {
        return _getBaseVaultStorage()._maxRewardsClaimDelay;
    }

    /**
     * @notice Set the maximum delay allowed between reward claims
     * @dev Updates the maximum time allowed between reward claims (must be between 1 day and 30 days)
     * @param _delay The maximum delay in seconds
     */
    function setMaxRewardsClaimDelay(uint256 _delay) external virtual onlyOwner {
        _validateMaxRewardsClaimDelay(_delay);
        _getBaseVaultStorage()._maxRewardsClaimDelay = _delay;
        emit MaxRewardsClaimDelayUpdated(_delay);
    }

    /**
     * @notice Calculate and charge withdrawal fees
     * @dev Calculates withdrawal fee based on protocol fee rate and sends it to fee receiver
     * @param _totalWithdrawalAmount The total amount being withdrawn
     * @return The fee amount charged
     */
    function _chargeWithdrawalFee(uint256 _totalWithdrawalAmount) internal returns (uint256) {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if (_totalWithdrawalAmount == 0) return 0;
        if ($._magma.withdrawalFee() == 0) return 0;
        uint256 _fee = Math.mulDiv(_totalWithdrawalAmount, $._magma.withdrawalFee(), BASE_BPS, Math.Rounding.Ceil);
        if (_fee > 0) {
            (bool okFee,) = $._magma.feeReceiver().call{value: _fee}("");
            if (!okFee) {
                emit WithdrawalFeeTransferFailed(_fee);
                return 0;
            } else {
                emit WithdrawalFeeTransferSuccess(_fee, $._magma.feeReceiver());
            }
        }
        return _fee;
    }

    /**
     * @notice Complete withdrawal process for a removed validator
     * @dev Finalizes validator removal by completing pending withdrawal and updating state
     * @param _valId The validator ID being removed
     * @return The amount withdrawn from the validator
     */
    function _completeValidatorRemovalWithdrawal(uint64 _valId) internal returns (uint256) {
        BaseVaultStorage storage $ = _getBaseVaultStorage();

        if ($._validatorStatus[_valId] != ValidatorStatus.UNDELEGATING) revert ErrInvalidStatus();

        // Check bitmap first - if ADMIN_WID is not in use, no pending withdrawal exists
        if (!$._withdrawalIdBitmaps[_valId].isWithdrawalIdInUse(ADMIN_WID)) {
            revert ErrNoPendingWithdrawRequest();
        }

        // Get the withdrawal amount before completing withdrawal
        (, uint256 _withdrawalAmount,,) = _getWithdrawalRequest(_valId, address(this), ADMIN_WID);
        if (!(_withdrawalAmount > 0)) revert ErrNoPendingWithdrawRequest();

        // Complete the withdrawal using the admin withdrawal ID
        $._totalPendingRedelegation -= $._pendingRedelegateByValidator[_valId];
        uint256 _beforeBal = address(this).balance;
        _completeRedelegationWithdrawal(_valId, ADMIN_WID);
        uint256 _delta = address(this).balance - _beforeBal;

        $._validatorStatus[_valId] = ValidatorStatus.REMOVED;
        emit ValidatorRemovalCompleted(_valId);

        return _delta;
    }

    /**
     * @notice Step 2: Remove validator from validators array this function forces all stake to be in an active state
     * @dev Remove validator from validators array
     * @param _valId The validator ID to remove
     */
    function _executeValidatorUndelegation(uint64 _valId) internal {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if ($._validatorStatus[_valId] != ValidatorStatus.PAUSED) revert ErrInvalidStatus();

        DelInfo memory _coreVaultDelInfo = _getDelegatorInfo(_valId, address(this));

        if (_coreVaultDelInfo.deltaStake > 0 || _coreVaultDelInfo.nextDeltaStake > 0) {
            revert ErrPendingStakeNotZero();
        }

        // Claim any accumulated rewards before removing validator
        if (_coreVaultDelInfo.rewards > 0) {
            _claimValidatorRewards(_valId);
        }

        uint256 _amountToRedelegate = _coreVaultDelInfo.stake;
        $._totalPendingRedelegation =
            $._totalPendingRedelegation - $._pendingRedelegateByValidator[_valId] + _amountToRedelegate;
        $._pendingRedelegateByValidator[_valId] = _amountToRedelegate;

        // Initiate undelegation of all remaining stake from this validator
        if (_amountToRedelegate > 0) {
            _checkFreeAdminWid(_valId); // Ensure admin withdrawal ID is available
            _allocateAdminWidAndUndelegate(_valId, _amountToRedelegate);
            // _trackCachedUndelegation(_amountToRedelegate) should not be called since we are already accounting _totalPendingRedelegation.
            $._validatorStatus[_valId] = ValidatorStatus.UNDELEGATING; // Move to final removal phase
            emit ValidatorRemoved(_valId);
        } else {
            // No stake to undelegate, validator removal is complete
            $._validatorStatus[_valId] = ValidatorStatus.REMOVED;
            emit ValidatorRemovalCompleted(_valId);
        }
    }

    /**
     * @notice Register a new validator in the vault
     * @dev Adds validator to the active validators list and marks as whitelisted
     * @param _valId The validator ID to register
     */
    function _registerValidator(uint64 _valId) internal {
        if (_valId == 0) revert ErrZeroValidatorId();
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if ($._isWhitelisted[_valId]) revert ErrAlreadyWhitelisted();

        $._validatorStatus[_valId] = ValidatorStatus.NONE;
        $._validators.push(_valId);
        $._isWhitelisted[_valId] = true;

        emit ValidatorAdded(_valId);
    }

    /**
     * @notice Initiate the removal process for a validator
     * @dev Pauses validator, removes from active list, and tracks pending redelegation
     * @param _valId The validator ID to remove
     */
    function _initiateValidatorRemoval(uint64 _valId) internal {
        _checkFreeAdminWid(_valId);
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if (!$._isWhitelisted[_valId]) revert ErrNotWhitelisted();

        // Step 1: Pause validator to prevent new delegations
        $._validatorStatus[_valId] = ValidatorStatus.PAUSED;
        $._isWhitelisted[_valId] = false;
        _removeValidatorFromArray(_valId); // Remove from active validators list

        // Track the total stake that will need to be redelegated
        uint256 _totalStakedToValidator = _getTotalStakedToValidator(_valId);
        if (_totalStakedToValidator > 0) {
            // Reserve this amount for pending redelegation tracking
            $._pendingRedelegateByValidator[_valId] = _totalStakedToValidator;
            $._totalPendingRedelegation += _totalStakedToValidator;
            _trackCachedUndelegation(_totalStakedToValidator);
        }

        emit ValidatorRemovalInitiated(_valId);
    }

    /**
     * @notice Get total stake delegated to all validators
     * @dev Calculates sum of stakes across all active validators
     * @return Total staked amount in wei
     */
    function _getTotalStakedToAllValidators() internal returns (uint256) {
        uint256 _total = 0;
        uint64[] memory _validators = getValidators();
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            _total += _getTotalStakedToValidator(_validators[_i]);
        }
        return _total;
    }

    /**
     * @notice Get total active stake across all validators using cached data
     * @dev Sums cached stake data for all validators to avoid expensive precompile calls
     * @return Total active stake amount across all validators from cached data
     */
    function _getCachedTotalStakedToAllValidators() internal view returns (uint256) {
        uint256 _total = 0;
        uint64[] memory _validators = getValidators();
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            (uint256 _validatorStake,) = _getCachedTotalStakedToValidator(_validators[_i]);
            _total += _validatorStake;
        }
        return _total;
    }

    /**
     * @notice Allocate withdrawal ID and initiate undelegation
     * @dev Allocates a free withdrawal ID and starts undelegation process
     * @param _valId The validator ID to undelegate from
     * @param _amount The amount to undelegate
     * @return _wid The allocated withdrawal ID
     */
    function _allocateWidAndUndelegate(uint64 _valId, uint256 _amount) internal returns (uint8 _wid) {
        _wid = _getBaseVaultStorage()._withdrawalIdBitmaps[_valId].allocateWithdrawalId();
        _undelegate(_valId, _amount, _wid);
        return _wid;
    }

    /**
     * @notice Allocate admin withdrawal ID and initiate undelegation
     * @dev Uses reserved admin withdrawal ID (255) for administrative operations
     * @param _valId The validator ID to undelegate from
     * @param _amount The amount to undelegate
     * @return _wid The admin withdrawal ID (always 255)
     */
    function _allocateAdminWidAndUndelegate(uint64 _valId, uint256 _amount) internal returns (uint8) {
        _getBaseVaultStorage()._withdrawalIdBitmaps[_valId].allocateAdminWid();
        _undelegate(_valId, _amount, ADMIN_WID);
        return ADMIN_WID;
    }

    /**
     * @dev Store withdrawal request information for tracking
     * @param _user The user making the withdrawal request
     * @param _amount The amount being withdrawn
     * @param _validator The validator from which to withdraw
     * @param _withdrawalId The withdrawal ID assigned
     */
    function _storeWithdrawalRequest(address _user, uint256 _amount, uint64 _validator, uint8 _withdrawalId) internal {
        _getBaseVaultStorage()._userWithdrawalRequests[_user].push(
            WithdrawalRequestInfo({amount: _amount, validator: _validator, withdrawalId: _withdrawalId})
        );
    }

    /**
     * @notice Get total active stake for a validator
     * @dev Returns current active stake plus pending stake changes
     * @param _valId The validator ID to query
     * @return Total active stake amount
     */
    function _getTotalStakedToValidator(uint64 _valId) internal returns (uint256) {
        DelInfo memory _delInfo = _getDelegatorInfo(_valId, address(this));
        return _delInfo.stake + _delInfo.deltaStake + _delInfo.nextDeltaStake;
    }

    /**
     * @notice Get total active stake for a validator using cached data
     * @dev Returns current active stake plus pending stake changes from cache
     * @param _valId The validator ID to query
     * @return Total active stake amount from cached data
     */
    function _getCachedTotalStakedToValidator(uint64 _valId) internal view returns (uint256, uint256) {
        DelInfo memory _delInfo = cachedDelegatorInfo(_valId);
        return (_delInfo.stake + _delInfo.deltaStake + _delInfo.nextDeltaStake, _delInfo.stake);
    }

    /**
     * @notice Complete all pending withdrawal requests for a user
     * @dev Processes all user withdrawal requests, charges fees, and transfers funds
     * @param _user The user address whose withdrawals to complete
     * @return _totalWithdrawn The total amount withdrawn before fees
     * @return _totalWithdrawnAfterFee The amount transferred to user after fees
     */
    function _completeUserWithdrawal(address _user)
        internal
        returns (uint256 _totalWithdrawn, uint256 _totalWithdrawnAfterFee)
    {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        WithdrawalRequestInfo[] storage _userRequests = $._userWithdrawalRequests[_user];
        if (_userRequests.length == 0) revert ErrNoPendingWithdrawRequest();

        uint256 _totalSuccessfulWithdrawals = 0;

        // Process each withdrawal request for this user
        for (uint256 i = 0; i < _userRequests.length; ++i) {
            WithdrawalRequestInfo storage _request = _userRequests[i];
            uint64 _valId = _request.validator;
            uint8 _withdrawalId = _request.withdrawalId;
            uint256 _beforeBal = address(this).balance;

            // Execute withdrawal from staking precompile
            _withdraw(_valId, _withdrawalId);
            uint256 _delta = address(this).balance - _beforeBal;

            _totalSuccessfulWithdrawals += _delta;
            emit WithdrawalPaymentSuccess(_valId, _withdrawalId, _user, _delta);

            // Update pending undelegation tracking (handle potential underflow from slashing)
            if (pendingUndelegateByValidator(_valId) >= _delta) {
                setPendingUndelegateByValidator(_valId, pendingUndelegateByValidator(_valId) - _delta);
            } else {
                // Prevent underflow in case of additional rewards during withdrawal period.
                setPendingUndelegateByValidator(_valId, 0);
            }

            // Update global pending undelegations (handle potential underflow)
            $._totalPendingUndelegations =
                (_delta > $._totalPendingUndelegations) ? 0 : ($._totalPendingUndelegations - _delta);

            // Mark withdrawal ID as completed and available for reuse
            _markWithdrawalCompleted(_valId, _withdrawalId);
        }

        // Clear all withdrawal requests for this user after processing
        delete $._userWithdrawalRequests[_user];

        // Send all accumulated ETH to user in a single transaction (gas efficient)
        if (_totalSuccessfulWithdrawals > 0) {
            uint256 _fee = _chargeWithdrawalFee(_totalSuccessfulWithdrawals);
            uint256 _remaining = _totalSuccessfulWithdrawals - _fee;

            // Transfer remaining funds to Magma contract which will forward to user
            (bool success,) = address($._magma).call{value: _remaining}("");
            if (!success) {
                revert ErrNativeTransferFailed();
            }

            _totalWithdrawn = _totalSuccessfulWithdrawals;
            _totalWithdrawnAfterFee = _remaining;
        }

        emit UserWithdrawalCompleted(_user, _totalWithdrawnAfterFee);
    }

    function _completeRedelegationWithdrawal(uint64 _valId, uint8 _withdrawalId) internal {
        _withdraw(_valId, _withdrawalId);
        // Mark the withdrawal as completed in the bitmap
        _markWithdrawalCompleted(_valId, _withdrawalId);
        setPendingRedelegateByValidator(_valId, 0);
    }

    /**
     * @dev Mark a withdrawal ID as free in the bitmap when withdrawal is completed
     * @param _valId The validator ID
     * @param _withdrawalId The withdrawal ID to mark as free
     */
    function _markWithdrawalCompleted(uint64 _valId, uint8 _withdrawalId) internal {
        _getBaseVaultStorage()._withdrawalIdBitmaps[_valId].markWithdrawalCompleted(_withdrawalId);
    }

    /**
     * @notice Check if admin withdrawal ID is available
     * @dev Reverts if admin withdrawal ID is already in use
     * @param _valId The validator ID to check
     */
    function _checkFreeAdminWid(uint64 _valId) internal view {
        if (_getBaseVaultStorage()._withdrawalIdBitmaps[_valId].isWithdrawalIdInUse(ADMIN_WID)) {
            revert ErrAdminWidInUse();
        }
    }

    /**
     * @dev Claim rewards for a specific validator and distribute them
     * @param _valId The validator ID to claim rewards for
     */
    function _claimValidatorRewards(uint64 _valId) internal virtual {
        uint256 _balanceBefore = address(this).balance;

        // Try to claim rewards from the validator - if there are no rewards, this will fail gracefully
        bool success = _claim(_valId);

        uint256 _balanceAfter = address(this).balance;
        uint256 _rewardsClaimed = _balanceAfter - _balanceBefore;

        if (_rewardsClaimed > 0 && success) {
            // Calculate and send fee to fee receiver
            uint256 _fee = _calculateRewardsFeeAndSend(_rewardsClaimed);

            uint256 _remaining = _rewardsClaimed - _fee;

            // Distribute remaining rewards using vault-specific strategy
            if (_remaining > 0) {
                _distributeClaimedRewardsFromRemoval(_remaining);
            }
        }
    }

    /**
     * @dev Distribute claimed rewards - default implementation forwards to CoreVault
     * @param _amount The amount of rewards to distribute
     */
    function _distributeClaimedRewardsFromRemoval(uint256 _amount) internal virtual {
        ICoreVault _coreVault = ICoreVault(_getBaseVaultStorage()._magma.coreVault());
        // Call delegate function on CoreVault to distribute to remaining validators
        _coreVault.delegate{value: _amount}();
    }

    /**
     * @notice Calculate rewards fee and send to fee receiver
     * @dev Calculates protocol rewards fee and transfers it to the designated receiver
     * @param _totalRewards The total rewards amount to calculate fee from
     * @return _fee The fee amount calculated and sent
     */
    function _calculateRewardsFeeAndSend(uint256 _totalRewards) internal returns (uint256 _fee) {
        BaseVaultStorage storage $ = _getBaseVaultStorage();

        _fee = Math.mulDiv(_totalRewards, $._magma.rewardsFee(), BASE_BPS, Math.Rounding.Ceil);
        if (_fee > 0) {
            // send fee to fee receiver
            (bool _ok,) = $._magma.feeReceiver().call{value: _fee}("");
            if (!_ok) {
                emit RewardsFeeTransferFailed(_fee);
                return 0;
            } else {
                emit RewardsFeeTransferSuccess(_fee, $._magma.feeReceiver());
            }
        }
        return _fee;
    }

    /**
     * @dev Track delegation operations in cache to maintain accurate totalAssets calculation
     * @param _amount Amount being delegated
     */
    function _trackCachedDelegation(uint256 _amount) internal {
        _getBaseVaultStorage()._cachedTotalNetPendingDelegations += int256(_amount);
    }

    /**
     * @dev Track undelegation operations in cache to maintain accurate totalAssets calculation
     * @param _amount Amount being undelegated
     */
    function _trackCachedUndelegation(uint256 _amount) internal {
        _getBaseVaultStorage()._cachedTotalNetPendingDelegations -= int256(_amount);
    }

    /**
     * @dev Check if rewards need to be claimed based on the maximum delay
     * @notice Reverts if rewards haven't been claimed within the maximum allowed delay
     */
    function _checkRewardsClaimDelay() internal view virtual {
        BaseVaultStorage storage $ = _getBaseVaultStorage();
        if (block.timestamp - $._lastRewardsClaimTimestamp > $._maxRewardsClaimDelay) {
            revert ErrRewardsClaimOverdue();
        }
    }

    /**
     * @dev Update the last rewards claim timestamp
     * @notice Should be called whenever rewards are claimed from all validators
     */
    function _updateLastRewardsClaimTimestamp() internal virtual {
        _getBaseVaultStorage()._lastRewardsClaimTimestamp = block.timestamp;
    }

    /**
     * @dev Validate the maximum rewards claim delay parameter
     * @notice Shared validation logic for both vault types
     * @param _delay The delay to validate (must be between 1 day and 30 days)
     */
    function _validateMaxRewardsClaimDelay(uint256 _delay) internal pure {
        if (_delay < 1 days || _delay > 30 days) revert ErrInvalidAmount(_delay);
    }

    /**
     * @dev Check if a withdrawal ID is in use for a validator
     * @param _valId The validator ID
     * @param _withdrawalId The withdrawal ID to check
     * @return true if the withdrawal ID is in use, false otherwise
     */
    function _isWithdrawalIdInUse(uint64 _valId, uint8 _withdrawalId) internal view returns (bool) {
        return _getBaseVaultStorage()._withdrawalIdBitmaps[_valId].isWithdrawalIdInUse(_withdrawalId);
    }
}

src/CoreVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.30;

import {Initializable} from "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import {UUPSUpgradeable} from "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import {ReentrancyGuardUpgradeable} from "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import {DelInfo} from "./MagmaDelegationModule.sol";
import {ICoreVault} from "../interfaces/ICoreVault.sol";
import {BaseVault} from "./BaseVault.sol";
import {
    ErrEpochGuard,
    ErrMaxValidators,
    ErrRebalanceInProgress,
    ErrNotEnoughValidators,
    ErrNotMagma,
    ErrBelowMinWithdraw,
    ErrNoValidators,
    ErrExistingWithdrawalInProgress,
    ErrInsufficientDelegated,
    ErrZeroAmount,
    ErrInvalidAmount,
    ErrNotAuthorized,
    ErrValidatorInRemoval
} from "./MagmaErrorsModule.sol";

contract CoreVault is Initializable, UUPSUpgradeable, ReentrancyGuardUpgradeable, ICoreVault, BaseVault {
    /// @custom:storage-location erc7201:storage.CoreVault
    struct CoreVaultStorage {
        /// @dev Maximum number of validators that can be added in a single batch to prevent gas limit issues
        uint64 _maxValidatorPerBatch;
    }

    /// @dev Struct to hold validator ID and associated amount for sorting operations
    struct ValidatorAmount {
        uint64 valId; // Validator identifier
        uint256 amount; // Stake amount associated with this validator
    }

    // keccak256(abi.encode(uint256(keccak256("storage.CoreVault")) - 1)) & ~bytes32(uint256(0xff))
    /* solhint-disable-next-line const-name-snakecase */
    bytes32 private constant _CoreVaultStorageLocation =
        0x52cc5b10e48806cc3038884ee015a89dc6583650d30099489137fff04e064c00;

    // whenNotPaused modifier is now inherited from PausableUpgradeable
    modifier onlyAfterEpoch() {
        if (epochSeconds() != 0) {
            if (block.timestamp < lastRebalanceTimestamp() + epochSeconds()) {
                revert ErrEpochGuard();
            }
        }
        _;
    }

    /// @dev https://forum.openzeppelin.com/t/is-disableinitializers-necessary/31070
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /**
     * @notice Initialize the CoreVault contract with configuration parameters
     * @dev Sets up the vault with Magma protocol address and epoch timing configuration
     * @param _magma The address of the Magma protocol contract
     * @param _epochSeconds The duration of each epoch in seconds (0 disables epoch guard)
     * @param maxValidatorPerBatch_ The maximum number of validators that can be added in a single batch
     */
    function initialize(address _magma, uint256 _epochSeconds, uint64 maxValidatorPerBatch_) external initializer {
        __UUPSUpgradeable_init();
        __ReentrancyGuard_init();
        __BaseVault_init(_magma, _epochSeconds);
        CoreVaultStorage storage $ = _getCoreVaultStorage();
        $._maxValidatorPerBatch = maxValidatorPerBatch_;
    }

    function _getCoreVaultStorage() private pure returns (CoreVaultStorage storage $) {
        assembly {
            $.slot := _CoreVaultStorageLocation
        }
    }

    // --------------------------------------------------------------------------------------------------------------
    // Validator management functions
    // --------------------------------------------------------------------------------------------------------------

    /**
     * @notice Register a new validator in the vault
     * @dev Adds validator to the active validators list and marks as whitelisted
     * @param _valId The validator ID to register
     */
    function _addValidator(uint64 _valId) private {
        if (validatorStatus(_valId) != ValidatorStatus.NONE && validatorStatus(_valId) != ValidatorStatus.REMOVED) {
            revert ErrValidatorInRemoval();
        }
        _registerValidator(_valId);
    }

    /**
     * @notice Step 1: Add a validator and initiate rebalance phase 1 (undelegation)
     * @dev Add a validator and trigger excess undelegation. Redistribution must be done manually via redelegateToValidators()
     * @dev Can re-add a validator that was removed
     * @param _valId The validator ID to add
     */
    function addValidator(uint64 _valId) external onlyOwner onlyAfterEpoch {
        _addValidator(_valId);
        _refreshCache();
        _redelegateInitiate();
    }

    /**
     * @notice Add multiple validators and initiate rebalancing phase 1 (undelegation)
     * @dev Batch add validators with gas limit protection, then trigger rebalancing
     * @param validatorIds Array of validator IDs to add (limited by _maxValidatorPerBatch)
     */
    function addValidators(uint64[] calldata validatorIds) external onlyOwner onlyAfterEpoch {
        CoreVaultStorage storage $ = _getCoreVaultStorage();
        if (validatorIds.length > $._maxValidatorPerBatch) revert ErrMaxValidators($._maxValidatorPerBatch);

        for (uint256 i = 0; i < validatorIds.length; ++i) {
            _addValidator(validatorIds[i]);
        }
        _refreshCache(); // refreshing cache after adding validators to ensure new validator inclusion in cache
        _redelegateInitiate();
    }

    /**
     * @notice Phase 1: Initiate manual rebalancing by undelegating excess from over-target validators
     * @dev Starts the two-phase rebalancing process. Must be followed by redelegateToValidators()
     *      to complete the redistribution. Prevents concurrent rebalances.
     */
    function adminRebalanceInitiate() external onlyOwner onlyAfterEpoch {
        _refreshCache();
        if (!finishedLastRebalance()) revert ErrRebalanceInProgress();
        setFinishedLastRebalance(false);
        _redelegateInitiate();
    }

    /**
     * @notice Step 2: Redistribute to validators called after addValidator and adminRebalanceInitiate
     * @dev Completes pending withdrawals and redistributes funds to balance validator stakes
     */
    function redelegateToValidators() external onlyOwner {
        _refreshCache();
        _redelegateRedistribute();
    }

    /**
     * @notice Step 1: Initiate validator removal by adding to pendingRemovalValidators this way no new delegations
     *  can be made to the validator and we can ensure that the validator does not have pending stake stuck in the pending epochs (50k blocks, 5.5 hours)
     * @dev Initiate validator removal by adding to pendingRemovalValidators
     * @param _valId The validator ID to remove
     */
    function initiateValidatorRemoval(uint64 _valId) external onlyOwner {
        _refreshCache();
        if (validatorsLength() == 1) revert ErrNotEnoughValidators();
        _initiateValidatorRemoval(_valId);
    }

    /**
     * @notice Step 2: Remove validator from validators array this function forces all stake to be in an active state
     * @dev Remove validator from validators array
     * @param _valId The validator ID to remove
     */
    function executeValidatorUndelegation(uint64 _valId) external onlyOwner {
        _refreshCache();
        _executeValidatorUndelegation(_valId);
    }

    /**
     * @dev Complete the withdrawal process for a removed validator
     * This should be called after the WITHDRAWAL_DELAY period has passed
     * @param _valId The validator ID that was removed
     */
    function completeValidatorRemovalWithdrawal(uint64 _valId) external onlyOwner {
        _refreshCache();
        uint256 _withdrawalAmount = _completeValidatorRemovalWithdrawal(_valId);
        // Distribute the recovered funds to remaining validators
        if (_withdrawalAmount > 0) {
            _distributeToNextValidator(_withdrawalAmount);
        }
    }

    // --------------------------------------------------------------------------------------------------------------
    // Delegation functions
    // --------------------------------------------------------------------------------------------------------------

    /**
     * @notice Delegate native MON to validators equally
     * @dev Distributes the sent MON equally among all registered validators.
     *      Only callable by Magma protocol or gVault contract.
     */
    function delegate() external payable whenNotPaused {
        if (msg.sender != address(magma()) && msg.sender != magma().gVault()) {
            revert ErrNotMagma();
        }
        // Check if rewards need to be claimed before delegating
        _checkRewardsClaimDelay();
        _distributeToNextValidator(msg.value);
    }

    /**
     * @notice Initiate undelegation of specified amount for a user
     * @dev Creates withdrawal requests by undelegating from validators with highest stake first.
     *      Enforces minimum withdrawal amount and prevents multiple concurrent withdrawals per user.
     * @param _amount The amount of ETH to undelegate
     * @param _user The user address requesting the withdrawal
     */
    function undelegate(uint256 _amount, address _user) external onlyMagma whenNotPaused {
        if (_amount < minUserWithdrawAmount()) {
            revert ErrBelowMinWithdraw(minUserWithdrawAmount());
        }
        if (validatorsLength() == 0) revert ErrNoValidators();

        // Check if rewards need to be claimed before undelegating
        _checkRewardsClaimDelay();

        // only one withdrawal per user
        if (userWithdrawalRequests(_user).length > 0) revert ErrExistingWithdrawalInProgress();

        // Get validators and sort by active stake (highest first)
        (ValidatorAmount[] memory _validatorsWithActiveStake, uint256 _totalActiveStake) =
            _getValidatorsActiveStakeAndTotal();
        _sortDescendingByAmount(_validatorsWithActiveStake);

        uint256 _remainingAmount = _amount;
        uint256 _onetwentiethThreshold = _totalActiveStake / 20; // 1/20th of total active stake across all validators

        for (uint256 _i = 0; _i < _validatorsWithActiveStake.length && _remainingAmount > 0; ++_i) {
            uint64 _valId = _validatorsWithActiveStake[_i].valId;
            uint256 _availableStake = _validatorsWithActiveStake[_i].amount; // Use stake from sorted array

            if (_availableStake == 0) continue;

            // Check if request exceeds 1/20th of total active stake to prevent large withdrawals from single validator
            uint256 _maxAllowedFromValidator =
                _remainingAmount > _onetwentiethThreshold ? _onetwentiethThreshold : _remainingAmount;

            // Calculate amount to withdraw from this validator (min of needed, allowed, and available)
            uint256 _amountFromValidator = _remainingAmount;

            if (_amountFromValidator > _maxAllowedFromValidator) {
                _amountFromValidator = _maxAllowedFromValidator; // Respect the 5% limit per validator
            }
            if (_amountFromValidator > _availableStake) {
                _amountFromValidator = _availableStake; // Can't withdraw more than what's staked
            }

            if (_amountFromValidator > 0) {
                uint8 _wid = _allocateWidAndUndelegate(_valId, _amountFromValidator);

                // Store withdrawal request information
                _storeWithdrawalRequest(_user, _amountFromValidator, _valId, _wid);

                // Track pending; do not lower local delegated until completion
                setPendingUndelegateByValidator(_valId, pendingUndelegateByValidator(_valId) + _amountFromValidator);
                _remainingAmount -= _amountFromValidator;
            }
        }

        setTotalPendingUndelegations(totalPendingUndelegations() + _amount);
        _trackCachedUndelegation(_amount);

        // If we couldn't fulfill the full amount, revert
        if (_remainingAmount > 0) {
            revert ErrInsufficientDelegated(_amount, _amount - _remainingAmount);
        }
    }

    /**
     * @notice Complete withdrawal for a specific user's undelegation requests
     * @dev Processes all withdrawal requests for the user and returns total amount distributed
     * @param _user The user whose withdrawal requests to complete
     * @return _totalWithdrawn The actual amount successfully withdrawn and sent to the user
     * @return _totalWithdrawnAfterFee The amount withdrawn after applying withdrawal fees
     */
    function completeUserWithdrawal(address _user)
        external
        nonReentrant
        onlyMagma
        returns (uint256 _totalWithdrawn, uint256 _totalWithdrawnAfterFee)
    {
        return _completeUserWithdrawal(_user);
    }

    /**
     * @notice Get all registered validator IDs
     * @dev Returns array of validator IDs currently registered in the vault
     * @return Array of validator IDs
     */
    function getValidators() public view override(BaseVault, ICoreVault) returns (uint64[] memory) {
        return super.getValidators();
    }

    /**
     * @notice Get the total number of registered validators
     * @dev Returns the count of validators currently registered in the vault
     * @return The number of registered validators
     */
    function getValidatorCount() external view returns (uint256) {
        return validatorsLength();
    }

    /**
     * @notice Get total amount delegated across all validators
     * @dev Calculates and returns the sum of all delegated amounts including pending stakes
     * @return Total delegated amount in wei
     */
    function getTotalDelegated() external returns (uint256) {
        uint256 _total = 0;
        uint64[] memory _validators = getValidators();
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            _total += _getTotalStakedToValidator(_validators[_i]);
        }
        return _total;
    }

    /**
     * @notice Get total amount delegated to a specific validator
     * @dev Returns the total stake (active + pending) for the specified validator
     * @param _valId The validator ID to query
     * @return Total delegated amount to the validator in wei
     */
    function delegatedAmount(uint64 _valId) external returns (uint256) {
        return _getTotalStakedToValidator(_valId);
    }

    /**
     * @notice Claim staking rewards from all validators and redistribute them
     * @dev Claims rewards from all validators, deducts protocol fees, and redistributes
     *      remaining rewards equally among validators for compound staking.
     */
    function claimAndCompoundRewards() external nonReentrant {
        _claimAndCompoundRewards();
    }
    //--------------------------------------------------------------------------------------------------------------
    // Internal functions
    //--------------------------------------------------------------------------------------------------------------

    /**
     * @notice Internal function to claim and compound staking rewards
     * @dev Claims rewards from all validators, calculates fees, and redistributes remaining rewards
     */
    function _claimAndCompoundRewards() internal {
        uint256 _startingBalance = address(this).balance;
        uint64[] memory _validators = getValidators();
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint256 _before = address(this).balance;
            _claim(_validators[_i]);
            emit RewardsClaimed(_validators[_i], address(this).balance - _before);
        }
        uint256 _endingBalance = address(this).balance;
        uint256 _rewards = _endingBalance - _startingBalance;

        if (_rewards > 0) {
            uint256 _fee = _calculateRewardsFeeAndSend(_rewards);

            uint256 _remaining = _rewards - _fee;
            _distributeToNextValidator(_remaining);
        }

        // Update the last rewards claim timestamp since we claimed from all validators
        _updateLastRewardsClaimTimestamp();
    }

    /**
     * @dev Override BaseVault._distributeClaimedRewardsFromRemoval to use internal distribution
     * @param _amount The amount of rewards to distribute
     */
    function _distributeClaimedRewardsFromRemoval(uint256 _amount) internal override {
        // Use internal distribution instead of external delegate call
        _distributeToNextValidator(_amount);
    }

    /**
     * @notice Internal function to initiate rebalancing by undelegating excess stakes
     * @dev Calculates target delegation per validator and undelegates excess from over-target validators
     */
    function _redelegateInitiate() internal {
        uint64[] memory _validators = getValidators();
        if (_validators.length == 0) return;

        uint256 _totalDelegated = _getCachedTotalStakedToAllValidators();
        if (_totalDelegated == 0) return;

        uint256 _targetPerValidator = _totalDelegated / _validators.length;
        uint256 _totalToUndelegate = 0;
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint64 _v = _validators[_i];
            // Check if validator has sufficient active stake for undelegation
            // Use cached data to get available stake for undelegation
            (uint256 _validatorStake, uint256 _availableStake) = _getCachedTotalStakedToValidator(_v);
            if (_validatorStake > _targetPerValidator) {
                uint256 _excess = _validatorStake - _targetPerValidator;

                // Undelegate the minimum of what we want and what's available
                uint256 _toUndelegate = _excess < _availableStake ? _excess : _availableStake;

                if (_toUndelegate > 0) {
                    _checkFreeAdminWid(_v);
                    _allocateAdminWidAndUndelegate(_v, _toUndelegate);
                    // Track pending excess; keep local delegated until completion
                    setPendingRedelegateByValidator(_v, _toUndelegate);
                    _totalToUndelegate += _toUndelegate;
                }
            }
        }
        if (_totalToUndelegate > 0) {
            setTotalPendingRedelegation(totalPendingRedelegation() + _totalToUndelegate);
            _trackCachedUndelegation(_totalToUndelegate);
        }

        setLastRebalanceTimestamp(block.timestamp);

        emit RebalanceInitiated(_totalToUndelegate, _validators.length, _targetPerValidator, _totalDelegated);
    }

    /**
     * @notice Internal function to complete rebalancing by redistributing undelegated funds
     * @dev Completes pending withdrawals and redistributes funds to under-target validators
     */
    function _redelegateRedistribute() internal {
        // Step 1: Complete all pending withdrawals
        uint256 _totalAmountToDistribute = _completeAllPendingRedelegationWithdrawals();

        if (_totalAmountToDistribute == 0) return;

        // Step 2: Get validators sorted by current stake (lowest first)
        ValidatorAmount[] memory _sortedValidators = _getSortedValidatorsByStake();

        // Step 3: Distribute stake to under-target validators in ascending order of stake
        _distributeStakeToValidatorsAscending(_sortedValidators, _totalAmountToDistribute);

        // Step 4: Update timestamp and mark rebalance as finished
        setLastRebalanceTimestamp(block.timestamp);
        setFinishedLastRebalance(true);
    }

    /**
     * @notice Complete all pending withdrawals for admin withdrawal ID
     * @dev Internal helper function that completes withdrawals and returns total amount withdrawn
     * @return _totalWithdrawn The total amount withdrawn from all validators
     */
    function _completeAllPendingRedelegationWithdrawals() internal returns (uint256 _totalWithdrawn) {
        uint64[] memory _validators = getValidators();
        uint256 _beforeBal = address(this).balance;
        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint64 _valId = _validators[_i];

            // Check bitmap first - if ADMIN_WID is not in use, skip expensive precompile call
            if (!_isWithdrawalIdInUse(_valId, ADMIN_WID)) {
                continue;
            }

            (, uint256 _amount,,) = _getWithdrawalRequest(_valId, address(this), ADMIN_WID);
            if (_amount > 0) {
                // For admin withdrawals, we need to handle pending redelegation amounts
                _withdraw(_valId, ADMIN_WID);
                // Update pending redelegation tracking

                // Note: in the case where the withdrawal is slashed we use the cached amount to deduct from totalPendingRedelegation
                setTotalPendingRedelegation(totalPendingRedelegation() - pendingRedelegateByValidator(_valId));
                setPendingRedelegateByValidator(_valId, 0);

                // Mark withdrawal ID as completed
                _markWithdrawalCompleted(_valId, ADMIN_WID);
            }
        }
        uint256 _delta = address(this).balance - _beforeBal;
        _totalWithdrawn += _delta;
    }

    /**
     * @notice Get validators sorted by their current stake (lowest first)
     * @dev Internal helper function that builds array of validators with current stakes and sorts them
     * @return _sortedValidators Array of ValidatorAmount structs sorted by stake amount (ascending)
     */
    function _getSortedValidatorsByStake() internal view returns (ValidatorAmount[] memory _sortedValidators) {
        uint64[] memory _validators = getValidators();
        _sortedValidators = new ValidatorAmount[](_validators.length);

        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint64 _valId = _validators[_i];
            DelInfo memory _coreVaultDelInfo = cachedDelegatorInfo(_valId);
            _sortedValidators[_i] = ValidatorAmount(
                _valId, _coreVaultDelInfo.stake + _coreVaultDelInfo.deltaStake + _coreVaultDelInfo.nextDeltaStake
            );
        }

        _sortAscendingByAmount(_sortedValidators);
    }

    /**
     * @notice Get validators with their active stake
     * @return _validatorsWithActiveStake Array of ValidatorAmount structs
     * @return _activeStake Active stake across all validators
     */
    function _getValidatorsActiveStakeAndTotal()
        internal
        view
        returns (ValidatorAmount[] memory _validatorsWithActiveStake, uint256 _activeStake)
    {
        uint64[] memory _validators = getValidators();
        _validatorsWithActiveStake = new ValidatorAmount[](_validators.length);
        _activeStake = 0;

        for (uint256 _i = 0; _i < _validators.length; ++_i) {
            uint64 _valId = _validators[_i];
            DelInfo memory _coreVaultDelInfo = cachedDelegatorInfo(_valId);
            uint256 _validatorStake = _coreVaultDelInfo.stake;
            _validatorsWithActiveStake[_i] = ValidatorAmount(_valId, _validatorStake);
            _activeStake += _validatorStake;
        }
    }

    /**
     * @notice Distribute stake to under-target validators
     * @dev Internal helper function that calculates targets and distributes stake to validators needing more
     * @param _sortedValidators Array of validators sorted by current stake (lowest first)
     * @param _totalAmountToDistribute Total amount available for distribution
     */
    function _distributeStakeToValidatorsAscending(
        ValidatorAmount[] memory _sortedValidators,
        uint256 _totalAmountToDistribute
    ) internal {
        if (_totalAmountToDistribute == 0) return;

        // Calculate total current stake to determine new target
        uint256 _currentTotalStake = 0;
        for (uint256 _i = 0; _i < _sortedValidators.length; ++_i) {
            _currentTotalStake += _sortedValidators[_i].amount;
        }

        uint256 _newTotalStake = _currentTotalStake + _totalAmountToDistribute;
        uint256 _targetAmountPerValidator = _newTotalStake / validatorsLength();
        uint256 _remainingToDistribute = _totalAmountToDistribute;

        // Distribute to under-target validators, starting with lowest stake to achieve balance
        for (uint256 _i = 0; _i < _sortedValidators.length && _remainingToDistribute > 0; ++_i) {
            uint64 _valId = _sortedValidators[_i].valId;
            uint256 _currentAmount = _sortedValidators[_i].amount;

            // Only add stake to validators below the target amount
            if (_currentAmount < _targetAmountPerValidator) {
                uint256 _needed = _targetAmountPerValidator - _currentAmount;
                // Give this validator either what it needs or what we have left, whichever is smaller
                uint256 _toDelegate = _needed > _remainingToDistribute ? _remainingToDistribute : _needed;

                if (_toDelegate > 0) {
                    _delegate(_valId, _toDelegate);
                    _remainingToDistribute -= _toDelegate;
                }
            }
        }
        _trackCachedDelegation(_totalAmountToDistribute);
    }

    /**
     * @dev Distributes the specified amount to the validator with the lowest stake
     * @param _amount The total amount to distribute
     */
    function _distributeToNextValidator(uint256 _amount) internal {
        uint64[] memory _validators = getValidators();
        if (_validators.length == 0) {
            revert ErrNoValidators();
        }
        if (_amount == 0) {
            revert ErrZeroAmount();
        }

        (ValidatorAmount[] memory _validatorsWithActiveStake, uint256 _totalActiveStake) =
            _getValidatorsActiveStakeAndTotal();
        _sortAscendingByAmount(_validatorsWithActiveStake);

        uint256 _remainingAmount = _amount;
        uint256 _onetwentiethThreshold = _totalActiveStake / 20; // 1/20th of total active stake across all validators
        if (_totalActiveStake == 0) {
            // Send everything to the first (lowest-stake) validator
            uint64 _firstValId = _validatorsWithActiveStake[0].valId;
            _delegate(_firstValId, _remainingAmount);
            _remainingAmount = 0;
        } else {
            for (uint256 _i = 0; _i < _validatorsWithActiveStake.length && _remainingAmount > 0; ++_i) {
                uint64 _valId = _validatorsWithActiveStake[_i].valId;

                // Check if request exceeds 1/20th of total active stake
                uint256 _maxAllowedFromValidator =
                    _remainingAmount > _onetwentiethThreshold ? _onetwentiethThreshold : _remainingAmount;

                uint256 _amountToValidator = _remainingAmount;

                if (_amountToValidator > _maxAllowedFromValidator && _i < _validatorsWithActiveStake.length - 1) {
                    _amountToValidator = _maxAllowedFromValidator;
                }

                if (_amountToValidator > 0) {
                    _delegate(_valId, _amountToValidator);
                    _remainingAmount -= _amountToValidator;
                }
            }
        }

        // If we couldn't fulfill the full amount, deposit remaining to first validator
        if (_remainingAmount > 0) {
            uint64 _firstValId = _validatorsWithActiveStake[0].valId;
            _delegate(_firstValId, _remainingAmount);
        }
        _trackCachedDelegation(_amount);
    }

    function injectRewards() public payable whenNotPaused {
        if (msg.sender != magma().mevRewardsInjector()) revert ErrNotAuthorized();
        if (msg.value == 0) revert ErrZeroAmount();
        _distributeToNextValidator(msg.value);
        emit RewardsInjected(msg.value);
    }

    /**
     * @dev Simple insertion sort for ValidatorAmount array (ascending by amount)
     */
    function _sortAscendingByAmount(ValidatorAmount[] memory _arr) internal pure {
        uint256 _length = _arr.length;
        for (uint256 _i = 1; _i < _length; ++_i) {
            ValidatorAmount memory key = _arr[_i];
            uint256 _j = _i;
            while (_j > 0 && _arr[_j - 1].amount > key.amount) {
                _arr[_j] = _arr[_j - 1];
                --_j;
            }
            _arr[_j] = key;
        }
    }

    /**
     * @dev Simple insertion sort for ValidatorAmount array (descending by amount)
     */
    function _sortDescendingByAmount(ValidatorAmount[] memory _arr) internal pure {
        uint256 _length = _arr.length;
        for (uint256 _i = 1; _i < _length; ++_i) {
            ValidatorAmount memory key = _arr[_i];
            uint256 _j = _i;
            while (_j > 0 && _arr[_j - 1].amount < key.amount) {
                _arr[_j] = _arr[_j - 1];
                --_j;
            }
            _arr[_j] = key;
        }
    }

    /**
     * @dev Get all withdrawal requests for a user
     * @param _user The user address
     * @return Array of withdrawal request information
     */
    function getUserWithdrawalRequests(address _user) external view returns (WithdrawalRequestInfo[] memory) {
        return userWithdrawalRequests(_user);
    }

    /**
     * @dev Get specific withdrawal request for a user by index
     * @param _user The user address
     * @param _index The index of the withdrawal request
     * @return The withdrawal request information
     */
    function getUserWithdrawalRequest(address _user, uint256 _index)
        external
        view
        returns (WithdrawalRequestInfo memory)
    {
        WithdrawalRequestInfo[] memory requests = userWithdrawalRequests(_user);
        if (_index >= requests.length) revert ErrInvalidAmount(_index);
        return requests[_index];
    }

    /**
     * @dev Get total number of withdrawal requests for a user
     * @param _user The user address
     * @return The total count of withdrawal requests for the user
     */
    function getUserWithdrawalRequestCount(address _user) external view returns (uint256) {
        return userWithdrawalRequests(_user).length;
    }

    /**
     * @notice Update the maximum number of validators that can be added in a single batch
     * @dev Admin function to adjust gas limit protection for batch validator operations
     * @param maxValidatorPerBatch New maximum batch size for validator additions
     */
    function setMaxValidatorPerBatch(uint64 maxValidatorPerBatch) external onlyOwner {
        _getCoreVaultStorage()._maxValidatorPerBatch = maxValidatorPerBatch;
    }

    /**
     * @notice Internal function to authorize contract upgrades
     * @dev Only allows the Magma admin to authorize upgrades. Required by UUPSUpgradeable
     * @dev https://docs.openzeppelin.com/contracts/5.x/api/proxy#UUPSUpgradeable
     */
    /* solhint-disable-next-line no-empty-blocks */
    function _authorizeUpgrade(address newImplementation) internal override onlyOwner {}
}

